def g_prime_power(p, a):
    # g(p^a) = p^a + a * p^(a-1)
    if a == 0:
        return 1
    return p**a + a * (p**(a-1))

def check_g_equals_2n(p, a):
    # Check if g(p^a) = 2 * p^a
    return g_prime_power(p, a) == 2 * (p**a)

# Check candidate primes up to 7
primes = [2, 3, 5, 7]
solutions = []
for p in primes:
    # We derived the condition a=p for g(p^a) = 2p^a
    # We only need to check a=p
    a = p
    n = p**a
    if n <= 4000:
        if check_g_equals_2n(p, a):
            solutions.append(n)
        else:
            # Safety check, should be True if the derivation was correct
            pass

print("Prime power solutions found: ", solutions)

